select

from purchase_suggest ps

   ps.is_deleted = false
   and exists (
     select 1 from purchase_suggest_merge psm,jsonb_array_elements_text(psm.source_id_json) AS source_id where psm.is_deleted = false and psm.status = 'draft' and psm.is_merge = false and source_id = ps.id
   )

      and ps.platform = #{platform}


      and ps.sku_id in

         #{item}



        and ps.suggest_purchase_date in

            #{item}
